-- Recruitment catalog seed, ported from the early hire-flow project
-- (supabase/migrations/20260813*..20260814*). Apply the schema alignment
-- first, then this data.

ALTER TABLE industries ADD COLUMN IF NOT EXISTS slug TEXT;
CREATE UNIQUE INDEX IF NOT EXISTS idx_industries_slug ON industries(slug);
ALTER TABLE job_titles ADD COLUMN IF NOT EXISTS job_family_id TEXT;
ALTER TABLE skill_library ADD COLUMN IF NOT EXISTS industry_slug TEXT;
CREATE UNIQUE INDEX IF NOT EXISTS idx_skill_library_name_category ON skill_library(name, category);
ALTER TABLE certification_library ADD COLUMN IF NOT EXISTS full_name TEXT;
ALTER TABLE certification_library ADD COLUMN IF NOT EXISTS industry_slug TEXT;
ALTER TABLE license_library ADD COLUMN IF NOT EXISTS classes TEXT;

